      "name": "Tender baby mangoes (kannimanga), whole",
      "amount": "1000g"
    },
    {
      "name": "Crystal sea salt",
      "amount": "150g"
    },
    {
      "name": "Kashmiri chilli powder",
      "amount": "50g"
    },
    {
      "name": "Gingelly (sesame) oil",
      "amount": "60g"
    },
    {
      "name": "Mustard seeds",
      "amount": "10g"
    },
    {
      "name": "Fenugreek powder, roasted",
      "amount": "5g"
    },
    {
      "name": "Asafoetida (hing)",
      "amount": "3g"
    }
  ],
  "method": "Wipe the mangoes dry — no water must touch them at any stage. Layer them\nwith the crystal salt in a sterilised bharani (ceramic pickle jar), close,\nand shake once daily. Over 10 to 14 days the salt draws out the mango's own\nbrine and the fruit ferments in it, turning olive-drab and pleasantly tangy.\nThen heat the gingelly oil, crackle the mustard seeds, switch off the heat,\nand stir in the chilli powder, fenugreek powder and asafoetida. Cool the\nspiced oil completely and fold it through the mangoes and their brine.\nReturn everything to the bharani. The pickle is eatable in a week but\nmatures over a month; it keeps a year at room temperature if only dry\nspoons ever enter the jar."
}
